            min-width: 200px;
        }

        .stat-label {
            font-size: 14px;
            color: #a8a8a8;
            margin-bottom: 8px;
            text-transform: uppercase;
        }

        .stat-value {
            font-size: 36px;
            font-weight: bold;
            color: #e94560;
        }

        .next-piece {
            width: 100px;
            height: 100px;
            background: #0f3460;
            border: 2px solid #e94560;
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            grid-template-rows: repeat(4, 1fr);
            gap: 0;
        }

        .next-piece .cell {
            border: 1px solid #0a2342;
        }

        .controls {
            margin-top: 20px;
            font-size: 12px;
            color: #a8a8a8;
            line-height: 1.8;
        }

        .button-group {
            display: flex;
            gap: 10px;
            margin-top: 20px;
        }

        button {
            flex: 1;
            padding: 10px 20px;
            background: #e94560;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-weight: bold;
            font-size: 14px;
        }

        button:hover {
            background: #c73650;
        }

        button:active {
            transform: scale(0.98);
        }

        .game-over {
            position: absolute;
            top: 50%;
            left: 50%;
